def h(cell, goal):
    return abs(cell[0] - goal[0]) + abs(cell[1] - goal[1])

def find_path(grid, start, goal):
    if grid[start[0]][start[1]] == '#':
        return []
    if grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    def compute_heuristic(cell):
        return h(cell, goal)

    def find_next(cells):
        with_costs = []
        for cell in cells:
            if grid[cell[0]][cell[1]] == '.':
                with_costs.append((cell, compute_heuristic(cell)))
        return with_costs

    cells = [start]
    cost = 0
    visited = set()
    movingnorth = moves = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    while cells:
        next_cells = []
        visited.update(cells)
        for cell in cells:
            for m in movingnorth:
                ncell = (cell[0] + m[0], cell[1] + m[1])
                if (0 <= ncell[0] < len(grid) and 0 <= ncell[1] < len(grid[0])) and (ncell not in visited):
                    if grid[ncell[0]][ncell[1]] == '.':
                        next_cells.append(ncell)
        if goal in next_cells:
            return [(goal, cost + 1)]
        cells = find_next(next_cells)
        cost += 1
    return []
