def solve(grid, start, goal):
    if grid[start[0]][start[1]] == '#':
        return []
    if start == goal:
        return [start]
    empty = BoundedQueues()
    empty.put(start)
    came_from = {start: None}
    max_len = inf
    while empty.get_last_dimensions()[0] == -1:
        len1 = empty.get_last_dimensions()[0]
        state = empty.pop()
        state_size = empty.size()
        if state == goal:
            path = []
            lenn = len1
            while state:
                path.append(state)
                state = came_from[state]
                lenn -= 1
            path.reverse()
            return path
        if len1 > max_len:
            if state_size > 0:
                empty.shuffle()
            continue
        for o in [(0,-1),(1,0),(0,1),(-1,0)]:
            r, c = (state[0] + o[0], state[1] + o[1])
            cell = (r % len(grid), c % len(grid[0]))
            if 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[cell[0]][cell[1]] == '.':
                empty.put(cell)
                came_from[cell] = state
    return []

class BoundedQueue:
    def __init__(self):
        self.items = []
        self.max_len = -1
    def put(self, item):
        self.items.append(item)
        self.max_len = max(len(self.items), self.max_len)
    def pop(self):
        self.max_len -= 1
        return self.items.pop()
    def get_last_dimensions(self):
        if self.max_len == -1:
            return (-1, -1)
        else:
            return (self.max_len, len(self.items[self.max_len]))
    def size(self):
        return len(self.items)
    def shuffle(self):
        shuffle(self.items)
