            return [start]
        visited = set()
        queue = deque()
        prev = {}
        queue.append(start)
        visited.add(start)
        while queue:
            current = queue.popleft()
            if current == goal:
                break
            for neighbor in get_neighbors(*current):
                if neighbor not in visited:
                    visited.add(neighbor)
                    prev[neighbor] = current
                    queue.append(neighbor)
        if goal not in prev:
            return []
        path = []
        current = goal
        while current != start:
            path.append(current)
            current = prev[current]
        path.append(start)
        return path[::-1]
