    distance = [[INF] * cols for _ in range(rows)]
    distance[start[0]][start[1]] = 0
    predecessor = [[None] * cols for _ in range(rows)]

    # Relax all edges up to V-1 times
    for _ in range(rows * cols - 1):
        updated = False
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == '#' or distance[r][c] == INF:
                    continue
                # Check all four directions
                for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        if grid[nr][nc] == '#':
                            continue
                        if distance[nr][nc] > distance[r][c] + 1:
                            distance[nr][nc] = distance[r][c] + 1
                            predecessor[nr][nc] = (r, c)
                            updated = True
        if not updated:
            break  # Early exit if no more updates

    # Check if goal is reachable
    if predecessor[goal[0]][goal[1]] is None:
        return []

    # Reconstruct path
    path = []
    current = goal
    while current is not None:
        path.append(current)
