def solve(grid, start, goal):
    sr, sc = start
    gr, gc = goal
    rows = len(grid)
    if rows == 0:
        return []
    cols = len(grid[0])

    def is_wall(r, c):
        return r < 0 or c < 0 or r >= rows or c >= cols or grid[r][c] != '.'

    if is_wall(sr, sc) or is_wall(gr, gc):
        return []

    if start == goal:
        return [start]

    directions = [ (-1,0), (0,1), (1,0), (0,-1) ]

    edges = []
    for i in range(rows):
        for j in range(cols):
            if is_wall(i, j):
                continue
            for di, dj in directions:
                ni, nj = i + di, j + dj
                if not is_wall(ni, nj):
                    u = i * cols + j
                    v = ni * cols + nj
                    edges.append( (u, v) )

    start_id = sr * cols + sc
    goal_id = gr * cols + gc
    N = rows * cols
    INF = float('inf')
    distance = [INF] * N
    predecessor = [None] * N
    distance[start_id] = 0

    for _ in range(N - 1):
        updated = False
        for u, v in edges:
            if distance[u] + 1 < distance[v]:
                distance[v] = distance[u] + 1
                predecessor[v] = u
                updated = True
        if not updated:
            break

    if distance[goal_id] == INF:
        return []

    path = []
    current = goal_id
    while current is not None:
        path.append(current)
        current = predecessor[current]
    path.reverse()

    result = [ (current // cols, current % cols) for current in path ]
    return result
